output_text:
[
  {
    "id": "no_cart_single_file_shelf_aisle",
    "text": "Shopping carts must not be taken into single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_pushcart_into_single_file",
    "text": "An agent may not move from a wider aisle into a single-file shelf aisle while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "pushCartIntoSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartIntoSingleFileAisle"
    }
  },
  {
    "id": "recover_cart_after_parking",
    "text": "If an agent parks a cart at a wide non-shelf aisle mouth, they are obliged to recover a cart before leaving.",
    "abstraction": {
      "state_properties": {
        "wideNonShelfAisle": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "parkCartAtAisleMouth": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "wideNonShelfAisle"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "recoverCartAtAisleMouth": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "wideNonShelfAisle"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtAisleMouth",
      "discharge": "recoverCartAtAisleMouth"
    }
  },
  {
    "id": "cartless_movement_only_in_cart_free_zones",
    "text": "Movement without a cart is allowed only at the entrance, in a cart-transfer mouth, or inside a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartTransferMouth": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "entranceCartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "allowedCartlessMovementOrigin": {
          "or": [
            "singleFileShelfAisle",
            "cartTransferMouth",
            "entranceCartArea"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "allowedCartlessMovementOrigin"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_open_shelf_service",
    "text": "Shelf interactions in open or cart-accessible aisles must be performed while holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfServicePoint": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfServicePoint",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "non_shelf_interactions_only_in_cart_zones",
    "text": "Non-shelf interactions, such as taking, dropping, or reclaiming a cart, may occur only in wide non-shelf cart zones.",
    "abstraction": {
      "state_properties": {
        "wideCartInteractionZone": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "adjShelf"
          },
          {
            "not": "wideCartInteractionZone"
          }
        ]
      }
    }
  },
  {
    "id": "park_cart_only_in_wide_non_shelf_space",
    "text": "A cart may be parked only in a wide non-shelf space, not beside shelves or in a bottleneck.",
    "abstraction": {
      "state_properties": {
        "legalCartParkingPlace": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "legalCartParkingPlace"
          }
        ]
      }
    }
  },
  {
    "id": "recover_after_cartless_single_file_pickup",
    "text": "After interacting with a shelf while cartless inside a single-file shelf aisle, the agent must later recover a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "INTERACT",
          "singleFileShelfAisle",
          {
            "not": "hasCart"
          }
        ]
      },
      "discharge": "hasCart"
    }
  }
]
